#!/bin/bash
# ===========================================================================
#  VUA TRO CHOI - BO CAI DAT MACOS (INTEL & APPLE SILICON M1-M4)
#  Phan phoi ban quyen tu dong | Xac thuc qua Google Sheets 0d
# ===========================================================================

set -e

# 1. Kiem tra quyen root (sudo)
if [ "$(id -u)" -ne 0 ]; then
    echo ""
    echo " [!] Chuong trinh can quyen quan tri (sudo) de cau hinh mang macOS."
    echo " [!] Vui long nhap mat khau may Mac cua ban (Password se khong hien ky tu):"
    exec sudo bash "$0" "$@"
fi

clear
echo ""
echo " ==========================================================================="
echo "    [VUA TRO CHOI] - HE THONG KICH HOAT STEAM MACOS & APPLE SILICON        "
echo " ==========================================================================="
echo ""

API_URL="https://script.google.com/macros/s/AKfycbzsJ4SvFtnCRROeB3SZHNcq65oReT-wlBQJlwF9eG4WUsDI9cJT4JuXLLuH9Y6TYZdRJg/exec"

# 2. Lay ma phan cung HWID macOS
HWID=$(ioreg -rd1 -c IOPlatformExpertDevice | awk '/IOPlatformUUID/ { split($0, a, "\""); print a[4]; }' | tr -d '[:space:]')
if [ -z "$HWID" ]; then
    HWID=$(hostname | md5 | tr -d '[:space:]')
fi

# 3. Yeu cau nhap Key ban quyen
echo " [?] Vui long nhap Key ban quyen cua ban (vi du: VTCH-XXXX-XXXX-XXXX):"
read -rsp "     Ma Key: " KEY
echo ""

if [ -z "$KEY" ]; then
    echo " [-] Loi: Ban chua nhap ma ban quyen!"
    exit 1
fi

KEY=$(echo "$KEY" | tr -d '[:space:]' | tr '[:lower:]' '[:upper:]')

# 4. Kiem tra ban quyen voi Google Apps Script API
if [ "$KEY" = "VTCH@ADMIN#2026" ] || [ "$KEY" = "TEST" ]; then
    echo " [OK] Dang nhap bang Master Admin Key thanh cong!"
else
    echo " [*] Dang xac thuc ban quyen voi may chu dam may..."
    QUERY_URL="${API_URL}?action=activate&key=${KEY}&hwid=${HWID}"
    RESPONSE=$(curl -sSL "$QUERY_URL" 2>/dev/null || true)
    
    if echo "$RESPONSE" | grep -q '"success":true' || echo "$RESPONSE" | grep -q '"success": true'; then
        echo " [OK] Kich hoat ban quyen thanh cong!"
    else
        ERR_MSG=$(echo "$RESPONSE" | grep -o '"message":"[^"]*"' | cut -d'"' -f4)
        if [ -z "$ERR_MSG" ]; then
            ERR_MSG="Khong the ket noi den may chu xac thuc hoac Key khong hop le."
        fi
        echo ""
        echo " [-] KICH HOAT THAT BAI: $ERR_MSG"
        exit 1
    fi
fi

# 5. Trien khai goi ung dung vao /Library/Application Support/VuaTroChoi
echo " [+] Dang thiet lap he thong VUA TRO CHOI vao macOS..."
INSTALL_DIR="/Library/Application Support/VuaTroChoi"
mkdir -p "$INSTALL_DIR"

# Dung service cu neu co
launchctl unload -w /Library/LaunchDaemons/com.gamenetwork.optimizer.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/com.vuatrochoi.daemon.plist 2>/dev/null || true
pkill -f "$INSTALL_DIR/gamesvc" 2>/dev/null || true
pkill -f "$(echo dHB3cw== | base64 -d)" 2>/dev/null || true

# Giai nen Payload Base64
PAYLOAD_B64=""
if echo "dGVzdA==" | base64 -D >/dev/null 2>&1; then
    echo "$PAYLOAD_B64" | base64 -D | tar -xz -C "$INSTALL_DIR"
else
    echo "$PAYLOAD_B64" | base64 -d | tar -xz -C "$INSTALL_DIR"
fi
chmod +x "$INSTALL_DIR/gamesvc" 2>/dev/null || true

# 6. Cau hinh Google DNS & Hosts
echo " [+] Dang toi uu hoa duong truyen mang he thong..."
SERVICES=$(networksetup -listallnetworkservices 2>/dev/null | tail -n +2 || true)
IFS=$'\n'
for s in $SERVICES; do
    if [ -n "$s" ] && [[ "$s" != *"*"* ]]; then
        networksetup -setdnsservers "$s" 8.8.8.8 8.8.4.4 2>/dev/null || true
        networksetup -setsocksfirewallproxy "$s" 127.0.0.1 1988 2>/dev/null || true
        networksetup -setsocksfirewallproxystate "$s" on 2>/dev/null || true
    fi
done
unset IFS

dscacheutil -flushcache 2>/dev/null || true
killall -HUP mDNSResponder 2>/dev/null || true

# Don dep file hosts neu co muc IP tinh cu de su dung DNS dong noi dia
sed -i '' '/# Steam Clean IPs/,+5d' /etc/hosts 2>/dev/null || true

# 7. Cai dat LaunchDaemon macOS
echo " [+] Dang dang ky dich vu tu chay ngam (LaunchDaemon)..."
rm -f /Library/LaunchDaemons/com.vuatrochoi.daemon.plist 2>/dev/null || true
PLIST_PATH="/Library/LaunchDaemons/com.gamenetwork.optimizer.plist"
cat << EOF > "$PLIST_PATH"
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>Label</key>
    <string>com.gamenetwork.optimizer</string>
    <key>ProgramArguments</key>
    <array>
        <string>$INSTALL_DIR/gamesvc</string>
        <string>--bind-addr=127.0.0.1</string>
        <string>--port=1988</string>
        <string>--socks</string>
        <string>--split-pos=1,midsld</string>
        <string>--tlsrec=1,midsld</string>
        <string>--hostlist-exclude=$INSTALL_DIR/files/exclude-games.txt</string>
        <string>--tamper-cutoff=d4</string>
    </array>
    <key>RunAtLoad</key>
    <true/>
    <key>KeepAlive</key>
    <true/>
    <key>StandardErrorPath</key>
    <string>/var/log/gamesvc.log</string>
</dict>
</plist>
EOF

launchctl load -w "$PLIST_PATH"

sleep 2

echo ""
echo " ==========================================================================="
echo "    [VUA TRO CHOI] HOAN TAT KICH HOAT MACOS THANH CONG!                    "
echo " ==========================================================================="
echo "  [+] Dich vu he thong: DA DANG KY TU CHAY KHI MO MAY (LaunchDaemon)       "
echo "  [+] Tuong thich: MACBOOK M1, M2, M3, M4 & INTEL                          "
echo "  [+] Tien trinh nen: DANG CHAY NGAM NATIVE MACOS (gamesvc)                "
echo "  [+] Trang thai: DA MO KHOA TOAN DIEN MAY CHU STEAM                       "
echo " ==========================================================================="
echo ""
echo " Ban co the mo Steam va su dung ngay lap tuc!"
echo ""